SELECT DISTINCT Cancer, Gene, "Gene name" FROM cancer_cptac
WHERE Gene IN ('ENSG00000051180','ENSG00000111206','ENSG00000125319','ENSG00000000460')
ORDER BY Gene, Cancer;

SELECT DISTINCT Ensembl, Gene FROM proteinatlas
WHERE Ensembl IN ('ENSG00000011426','ENSG00000051180','ENSG00000072571','ENSG00000088325','ENSG00000111206','ENSG00000125319','ENSG00000137807','ENSG00000175063','ENSG00000000460','ENSG00000013810')
ORDER BY Ensembl;
